package kr.pdfmemorynotes;
import android.content.Context;import android.graphics.*;import android.view.*;import android.util.AtomicFile;import java.io.*;import java.util.*;import org.json.*;
final class PdfCanvas extends View {
 Bitmap image;final Paint paint=new Paint(3);final RectF rect=new RectF();final File inkFile;JSONArray strokes=new JSONArray(),stroke;float cropTop,cropBottom,zoom=1,panX,panY,lastX,lastY;boolean drawing;final ScaleGestureDetector scale;
 PdfCanvas(Context c,String key){super(c);inkFile=new File(c.getFilesDir(),"ink-"+key+".json");try{if(inkFile.exists())strokes=new JSONArray(new String(java.nio.file.Files.readAllBytes(inkFile.toPath()),java.nio.charset.StandardCharsets.UTF_8));}catch(Exception ignored){}scale=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){zoom=Math.max(1,Math.min(4,zoom*d.getScaleFactor()));invalidate();return true;}});setContentDescription("PDF 원본. 두 손가락으로 확대, S펜으로 필기");}
 void image(Bitmap bitmap,float top,float bottom){if(image!=null&&!image.isRecycled())image.recycle();image=bitmap;cropTop=top;cropBottom=bottom;requestLayout();invalidate();}
 protected void onMeasure(int w,int h){int width=MeasureSpec.getSize(w);int height=image==null?200:(int)(width*(double)image.getHeight()/image.getWidth()*(cropBottom-cropTop));setMeasuredDimension(width,Math.max(40,height));}
 protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.WHITE);if(image==null)return;rect.set(0,0,getWidth(),getHeight());c.save();c.translate(panX,panY);c.scale(zoom,zoom,getWidth()/2f,getHeight()/2f);Rect src=new Rect(0,(int)(cropTop*image.getHeight()),image.getWidth(),Math.max(1,(int)(cropBottom*image.getHeight())));c.drawBitmap(image,src,rect,paint);paint.setColor(0xFFE86666);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2.5f);paint.setStrokeCap(Paint.Cap.ROUND);for(int i=0;i<strokes.length();i++)drawStroke(c,strokes.optJSONArray(i));drawStroke(c,stroke);paint.setStyle(Paint.Style.FILL);c.restore();}
 void drawStroke(Canvas c,JSONArray s){if(s==null)return;Path p=new Path();for(int i=0;i<s.length();i++){JSONArray q=s.optJSONArray(i);if(q==null)continue;float x=(float)q.optDouble(0)*getWidth(),y=((float)q.optDouble(1)-cropTop)/(cropBottom-cropTop)*getHeight();if(i==0)p.moveTo(x,y);else p.lineTo(x,y);}c.drawPath(p,paint);}
 void point(MotionEvent e){float x=((e.getX()-getWidth()/2f-panX)/zoom+getWidth()/2f)/Math.max(1,getWidth()),y=((e.getY()-getHeight()/2f-panY)/zoom+getHeight()/2f)/Math.max(1,getHeight());if(stroke!=null)try{stroke.put(new JSONArray().put(x).put(cropTop+y*(cropBottom-cropTop)));}catch(JSONException ignored){}}
 void reload(){try{if(inkFile.exists())strokes=new JSONArray(new String(java.nio.file.Files.readAllBytes(inkFile.toPath()),java.nio.charset.StandardCharsets.UTF_8));}catch(Exception ignored){}}
 void save(){AtomicFile f=new AtomicFile(inkFile);FileOutputStream out=null;try{out=f.startWrite();out.write(strokes.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);android.widget.Toast.makeText(getContext(),"필기 저장 실패: 저장 공간을 확인해 주세요",android.widget.Toast.LENGTH_SHORT).show();}}
 void undo(){reload();if(strokes.length()>0){strokes.remove(strokes.length()-1);save();invalidate();}}
 public boolean onTouchEvent(MotionEvent e){if(image==null)return false;int action=e.getActionMasked();boolean pen=e.getToolType(0)==MotionEvent.TOOL_TYPE_STYLUS||e.getToolType(0)==MotionEvent.TOOL_TYPE_ERASER;if(pen){if(action==0){drawing=true;stroke=new JSONArray();getParent().requestDisallowInterceptTouchEvent(true);}if(drawing){point(e);if(action==1){reload();strokes.put(stroke);stroke=null;drawing=false;save();getParent().requestDisallowInterceptTouchEvent(false);}if(action==3){stroke=null;drawing=false;getParent().requestDisallowInterceptTouchEvent(false);}invalidate();return true;}}scale.onTouchEvent(e);if(action==0){lastX=e.getX();lastY=e.getY();return true;}if(e.getPointerCount()>1||zoom>1){getParent().requestDisallowInterceptTouchEvent(true);if(action==2&&!scale.isInProgress()){panX+=e.getX()-lastX;panY+=e.getY()-lastY;float maxX=getWidth()*(zoom-1)/2,maxY=getHeight()*(zoom-1)/2;panX=Math.max(-maxX,Math.min(maxX,panX));panY=Math.max(-maxY,Math.min(maxY,panY));}lastX=e.getX();lastY=e.getY();invalidate();if(action==1||action==3)getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;}
 protected void onDetachedFromWindow(){super.onDetachedFromWindow();if(image!=null&&!image.isRecycled())image.recycle();image=null;}
}
